// Deriva competência YYYY-MM do mês atual
const now = new Date();
const competencia = now.getUTCFullYear() + '-' + String(now.getUTCMonth() + 1).padStart(2, '0');
const d = $input.first().json;
return [{ json: { ...d, competencia } }];

// Extrai apenas o objeto config e passa adiante
const j = $input.first().json;
return [{ json: { config: j.config ?? {} } }];

const items = $input.all();
const creds = $('Definir Competência').item.json;

let invoices = [];
let clients  = [];
let config   = {};

for (const item of items) {
  const j = item?.json;
  if (!j) continue;
  if (Array.isArray(j.invoices)) invoices = j.invoices;
  if (Array.isArray(j.clients))  clients  = j.clients;
  if (j.config && typeof j.config === 'object') config = j.config;
}

if (invoices.length === 0) {
  return [{ json: { skipped: true, reason: 'Nenhuma nota pendente para ' + creds.competencia } }];
}

const clientMap = {};
clients.forEach(function(c) { clientMap[c.id] = c; });

const notaasApiKey = creds.api_key || config.api_key;
if (!notaasApiKey) throw new Error('API Key da Notaas não configurada');

const batchItems = [];
const invoiceIds = [];
const skippedIds = [];

for (const inv of invoices) {
  const client = clientMap[inv.client_id];
  if (!client) {
    skippedIds.push({ id: inv.id, reason: 'cliente não encontrado' });
    continue;
  }

  const docDigits = (client.document || '').replace(/\D/g, '');
  const codigoServico = (inv.codigo_servico || config.codigo_servico_padrao || '').replace(/\D/g, '');
  if (!codigoServico) {
    skippedIds.push({ id: inv.id, reason: 'código de serviço não configurado' });
    continue;
  }

  const tomador = {};
  if (docDigits.length === 11) tomador.cpf  = docDigits;
  else                         tomador.cnpj = docDigits;
  tomador.nome  = client.company || client.name;
  tomador.email = client.email || null;
  tomador.endereco = {
    logradouro:  client.address_street       || '',
    numero:      client.address_number       || '',
    complemento: client.address_complement   || '',
    bairro:      client.address_neighborhood || '',
    cidade:      client.address_city         || '',
    uf:          client.address_state        || '',
    cep:         client.address_zip          || ''
  };

  batchItems.push({
    referencia:  inv.id,
    tomador,
    servico:     { codigo: codigoServico, descricao: inv.descricao_servico || config.descricao_servico_padrao || 'Prestação de serviços' },
    valores:     { total: inv.valor_servico, aliquotaIss: inv.aliquota_iss != null ? inv.aliquota_iss : (config.aliquota_iss_padrao || 5) },
    competencia: inv.competencia
  });
  invoiceIds.push(inv.id);
}

if (batchItems.length === 0) {
  return [{ json: { skipped: true, reason: 'Nenhum item válido para emitir', skippedIds } }];
}

return [{ json: {
  skipped:         false,
  batch_body:      { items: batchItems },
  invoice_ids:     invoiceIds,
  skipped_ids:     skippedIds,
  total:           batchItems.length,
  competencia:     creds.competencia,
  organization_id: creds.organization_id,
  api_key:         notaasApiKey,
  base_url:        creds.base_url
}}];

// Recebe o batchId da Notaas e atualiza os invoices para 'processando'
const batchResp = $input.first().json;
const prev      = $('Montar Batch').item.json;

const batchId   = batchResp.batchId || batchResp.batch_id || batchResp.id || null;
const invoiceIds = prev.invoice_ids || [];

// Retorna um item por invoice para o nó Supabase de update em seguida
return invoiceIds.map(function(id) {
  return { json: {
    invoice_id:  id,
    batch_id:    batchId,
    organization_id: prev.organization_id
  }};
});
